import createPDFiumModule from './pdfium.js';

const PDFBREEZE_TRANSFER_DB = 'pdfmint-editor-transfer';
const PDFBREEZE_TRANSFER_STORE = 'uploads';
const PDFBREEZE_TRANSFER_KEY = 'pending-pdf';

function openPdfBreezeTransferDb(){
  return new Promise((resolve,reject)=>{
    const request=indexedDB.open(PDFBREEZE_TRANSFER_DB,1);
    request.onupgradeneeded=()=>{
      const db=request.result;
      if(!db.objectStoreNames.contains(PDFBREEZE_TRANSFER_STORE))db.createObjectStore(PDFBREEZE_TRANSFER_STORE);
    };
    request.onsuccess=()=>resolve(request.result);
    request.onerror=()=>reject(request.error);
  });
}

async function takeTransferredPdf(){
  const db=await openPdfBreezeTransferDb();
  const record=await new Promise((resolve,reject)=>{
    const tx=db.transaction(PDFBREEZE_TRANSFER_STORE,'readwrite');
    const store=tx.objectStore(PDFBREEZE_TRANSFER_STORE);
    const request=store.get(PDFBREEZE_TRANSFER_KEY);
    request.onsuccess=()=>{
      const value=request.result||null;
      store.delete(PDFBREEZE_TRANSFER_KEY);
      resolve(value);
    };
    request.onerror=()=>reject(request.error);
  });
  db.close();
  if(!record)return null;
  return {
    file:new File([record.bytes],record.name,{type:record.type||'application/pdf',lastModified:record.lastModified||Date.now()}),
    completionNotice:record.completionNotice||null
  };
}

