window.pdfbreezeOpenExport=format=>{if(!doc)return false;if(liveEdit)finishLiveEditor();directPdfExport=false;const f=ui.exportFormats.querySelector(`[data-format="${CSS.escape(format)}"]`)?format:'pdf';setExportFormat(f);ui.exportFilename.value=exportBaseName();let swap=document.getElementById('exportSwapPdf');if(!swap){swap=document.createElement('button');swap.type='button';swap.id='exportSwapPdf';swap.className='export-swap-pdf';swap.textContent='Convert a different PDF';const input=document.createElement('input');input.type='file';input.accept='application/pdf,.pdf';input.hidden=true;swap.after(input);swap.addEventListener('click',()=>input.click());input.addEventListener('change',async()=>{const file=input.files[0];input.value='';if(!file)return;const want=exportFormat;closeExportModal();await openPdf(file);for(let i=0;i<100&&!doc;i++)await new Promise(r=>setTimeout(r,100));window.pdfbreezeOpenExport(want)});const anchor=ui.exportFilename.closest('label')||ui.exportFilename;anchor.after(swap);swap.after(input)}swap.hidden=false;ui.exportModal.hidden=false;return true};
