function checkoutUrl(extra=''){const source=new URLSearchParams(location.search).get('source'),params=new URLSearchParams({pdfiumCheckout:'1',format:exportFormat});if(source==='dashboard')params.set('source','dashboard');return `editor.html?${params}${extra}`}
async function hasPdfiumExportAccess(user){try{const auth=window.PDFMintAuth;if(!user||!auth?.client)return false;const{data,error}=await auth.client.from('subscriptions').select('plan_code,status,trial_ends_at').eq('user_id',user.id).in('status',['trialing','active']);if(error)throw error;const now=Date.now();return(data||[]).some(subscription=>{if(subscription.plan_code==='unlimited_trial'||subscription.plan_code==='annual')return true;return subscription.plan_code==='document_trial'&&subscription.status==='active'&&(!subscription.trial_ends_at||Date.parse(subscription.trial_ends_at)<=now)})}catch(error){console.warn('PDFBreeze could not verify membership access.',error);return false}}
function openExportEmailModal(user=null){exportIdentityUser=user;const action=`Download ${String(exportFormat||'pdf').toUpperCase()}`;ui.exportEmailModal.querySelectorAll('[data-email-action]').forEach(node=>{node.textContent=action});ui.exportModal.hidden=true;ui.exportEmailError.hidden=true;ui.exportEmail.readOnly=false;if(user?.email)ui.exportEmail.value=user.email;ui.exportEmailModal.hidden=false;setTimeout(()=>ui.exportEmail.focus(),50)}
