async function continueFromExportEmail(){const email=ui.exportEmail.value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ui.exportEmailError.hidden=false;ui.exportEmail.focus();return}ui.exportEmailError.hidden=true;ui.exportEmailContinue.disabled=true;ui.exportEmailContinue.classList.add('is-working');ui.exportEmailContinue.setAttribute('aria-busy','true');try{await window.PDFBreezeAnalytics?.track('email_entered');const sameIdentity=Boolean(exportIdentityUser?.email)&&exportIdentityUser.email.toLowerCase()===email.toLowerCase();if(exportIdentityUser&&!sameIdentity){const{error}=await window.PDFMintAuth?.client?.auth?.signOut({scope:'local'})||{};if(error)throw error;exportIdentityUser=null}sessionStorage.setItem('pdfmintPendingEmail',email);sessionStorage.setItem('pdfbreezePdfiumBridgeEmail',email);location.replace(checkoutUrl(sameIdentity?'':'&emailBridge=1'))}catch(error){ui.exportEmailError.textContent=error?.message||'PDFBreeze could not switch to that email. Please try again.';ui.exportEmailError.hidden=false;ui.exportEmailContinue.disabled=false;ui.exportEmailContinue.classList.remove('is-working');ui.exportEmailContinue.removeAttribute('aria-busy')}}
